properties.property:
[
  {
    "text":"I am an elf. I do elf things like hugging trees and being pretty.",
    "loctext": "adv.debug_map.80.d.n0.text",
    "options":[
      { "name":"OK", "locname": "adv.debug_map.80.d.n1.name" },
      {
        "name":"Fight me, elf!",
        "locname": "adv.debug_map.80.d.n3.name",
        "text": "Gladly.",
        "loctext": "adv.debug_map.80.d.n2.text",
        "options": [
          { "name": "Hey aren't you a bit swole for an elf...?", "locname": "adv.debug_map.80.d.n4.name", "action": [ { "battleWithActorID": -1 } ] }
        ]
      },
      {
        "name": "I want to be eco-friendly too.",
        "locname": "adv.debug_map.80.d.n6.name",
        "text": "Listen to the forest, friend.\nYour color identity is now green!",
        "loctext": "adv.debug_map.80.d.n5.text",
        "condition": [ { "colorIdentity": "G", "not": true } ],
        "options": [ { "name": "Awesome.", "locname": "adv.debug_map.80.d.n7.name", "action": [ { "setColorIdentity": "G" } ]} ]
      },
      {
        "name":"I wanna fight Emrakul over there!",
        "locname": "adv.debug_map.80.d.n9.name",
        "text": "Really? Oh well... your funeral.\nHEY EMMY! THIS CHUMP WANTS TO DANCE!",
        "loctext": "adv.debug_map.80.d.n8.text",
        "condition": [ { "actorID": 50 } ],
        "options": [ { "name": "WAIT IT WAS A JOKE!!!", "locname": "adv.debug_map.80.d.n10.name", "action": [ { "battleWithActorID": 50 } ]} ]
      },
      {
        "name":"Where did Emrakul go?",
        "locname": "adv.debug_map.80.d.n12.name",
        "text": "She left. Crying. You monster.",
        "loctext": "adv.debug_map.80.d.n11.text",
        "condition": [ { "actorID": 50, "not": true } ],
        "options": [ { "name": "Sorry...", "locname": "adv.debug_map.80.d.n13.name" } ]
      },
      {
        "name":"That's cool my green dude.",
        "locname": "adv.debug_map.80.d.n15.name",
        "text": "You get it! Take this item.",
        "loctext": "adv.debug_map.80.d.n14.text",
        "condition": [ { "item": "Treasure", "not": true }, { "colorIdentity": "G" } ],
        "action": [ { "addItem": "Treasure" } ],
        "options": [ { "name": "Thanks bro.", "locname": "adv.debug_map.80.d.n16.name" } ]
      },
      {
        "name":"Thanks for the blessing.",
        "locname": "adv.debug_map.80.d.n18.name",
        "text": "You are welcome.",
        "loctext": "adv.debug_map.80.d.n17.text",
        "condition": [ { "hasBlessing": "Debug Elf" } ],
        "options": [ { "name": "Thumbs up emoji", "locname": "adv.debug_map.80.d.n19.name" } ]
      },
      {
        "name":"Got any fancy elven blessing?",
        "locname": "adv.debug_map.80.d.n21.name",
        "text": "If you give me a Treasure, I will give you the blessing of the Debug Elf.\nWhich is a Llanowar Elves and 2 extra life in your next battle. Sounds good?",
        "loctext": "adv.debug_map.80.d.n20.text",
        "condition": [ { "item": "Treasure" }, { "hasBlessing":  "Debug Elf", "not": true } ],
        "options": [
          { "name": "But I love my Treasure! I humbly refuse.", "locname": "adv.debug_map.80.d.n22.name"},
          {
            "name": "I'll take it",
            "locname": "adv.debug_map.80.d.n23.name",
            "action": [
              { "removeItem": "Treasure", "giveBlessing": { "name": "Debug Elf" ,"goldModifier":0.2, "lifeModifier": 2, "startBattleWithCard": [ "Llanowar Elves" ] } }
            ]
          }
        ]
      },
      {
        "name":"Can you open that hidden wall?",
        "locname": "adv.debug_map.80.d.n25.name",
        "text": "Since you asked nicely, I shall.",
        "loctext": "adv.debug_map.80.d.n24.text",
        "condition": [ { "actorID": 83 } ],
        "options": [ { "name": "Thanks bro.", "locname": "adv.debug_map.80.d.n26.name", "action": [ { "deleteMapObject": 83 } ]} ]
      },
      {
        "name": "Got a quest?",
        "locname": "adv.debug_map.80.d.n28.name",
        "text": "Ah, perhaps you can help me. Can you ask the Debug Demon about his favorite color?",
        "loctext": "adv.debug_map.80.d.n27.text",
        "condition": [ { "checkQuestFlag":  "128", "not": true} ],
        "options": [
          { "name": "That's weird, but sure.", "locname": "adv.debug_map.80.d.n29.name", "action": [ { "setQuestFlag":  {"key":"128", "val": 1} } ] },
          { "name": "That guy scares me, I'd rather not.", "locname": "adv.debug_map.80.d.n30.name" }
        ]
      },
      {
        "name": "About that quest...",
        "locname": "adv.debug_map.80.d.n32.name",
        "text": "Please let me know what the Debug Demon's answer is.",
        "loctext": "adv.debug_map.80.d.n31.text",
        "condition": [ { "getQuestFlag":  { "key": "128", "op":"<", "val": 3 } } ],
        "options": [
          { "name": "Sure", "locname": "adv.debug_map.80.d.n33.name" }
        ]
      },
      {
        "name": "Got it, bro.",
        "locname": "adv.debug_map.80.d.n35.name",
        "text": "Ah. I see. Thank you friend, have this gold for your inconvenience.",
        "loctext": "adv.debug_map.80.d.n34.text",
        "condition": [ { "getQuestFlag":  { "key": "128", "op":"=", "val": 3 } } ],
        "options": [
          { "name": "Thanks", "locname": "adv.debug_map.80.d.n36.name", "action": [ { "setQuestFlag": {"key":"128", "val": 4}, "addGold": 250 } ] }
        ]
      }
    ]
  }
]

[
  {
    "text": "You...you hurt Grog!\nYou...you filthy swine! I will stop at nothing until I see you defeated!\nGods...anyone! Grant me strength! Grant me REVENGE!!!!",
    "loctext": "adv.debug_map.81.d.n0.text",
    "condition": [
      {
        "actorID": 82,
        "not": true
      }
    ],
    "options": [
      {
        "name": "Uh oh.",
        "locname": "adv.debug_map.81.d.n1.name",
        "action": [
          {
            "setEffect": {
              "lifeModifier": 99,
              "startBattleWithCard": [
                "Avacyn, Angel of Hope",
                "Urabrask the Hidden",
                "Elesh Norn, Grand Cenobite",
                "Emrakul, the Aeons Torn"
              ]
            }, "battleWithActorID": -1
          }
        ]
      }
    ]
  }
]

[
  {
    "text":"I have some things to offer for that life you have...",
    "loctext": "adv.debug_map.83.d.n0.text",
    "options":[
      { "name":"You are suspicious and have two shadows, I'm out.", "locname": "adv.debug_map.83.d.n1.name" },
      {
        "name":"I'll vanquish you, demon!",
        "locname": "adv.debug_map.83.d.n3.name",
        "text": "Oh look we got a tough guy over here!",
        "loctext": "adv.debug_map.83.d.n2.text",
        "options": [ { "name": "Have at thee!", "locname": "adv.debug_map.83.d.n4.name", "action": [ { "battleWithActorID": -1 } ]} ]
      },
      {
        "name": "I dig your edge.",
        "locname": "adv.debug_map.83.d.n6.name",
        "text": "You can be dark and edgy like me. Maybe for some of your life force...",
        "loctext": "adv.debug_map.83.d.n5.text",
        "condition": [ { "colorIdentity": "B", "not": true }, { "hasLife":  2 } ],
        "options": [
          { "name": "Not my life force, I'll die without it!", "locname": "adv.debug_map.83.d.n7.name" },
          { "name": "I'm doing nothing better with it.", "locname": "adv.debug_map.83.d.n8.name", "action": [ { "setColorIdentity": "B", "addLife": -2 } ] }
        ]
      },
      {
        "name": "I dig your edge.",
        "locname": "adv.debug_map.83.d.n10.name",
        "text": "You don't have enough life force...come back with more to offer.\nEat healthy, read a book, get that soul juicy.",
        "loctext": "adv.debug_map.83.d.n9.text",
        "condition": [ { "colorIdentity": "B", "not": true }, { "hasLife":  2, "not": true } ],
        "options": [ { "name": "Aw man...", "locname": "adv.debug_map.83.d.n11.name" } ]
      },
      {
        "name": "Any cool demon deals?",
        "locname": "adv.debug_map.83.d.n13.name",
        "text": "I can offer you this Treasure for the fair price of 200 gold.",
        "loctext": "adv.debug_map.83.d.n12.text",
        "condition": [ { "colorIdentity": "B" }, { "hasGold":  200 } ],
        "options": [
          { "name": "This gem has a lot of edge, just like me. Deal!", "locname": "adv.debug_map.83.d.n14.name" , "action": [ { "addGold": -200, "addItem": "Treasure" } ] },
          { "name": "I'll think about it.", "locname": "adv.debug_map.83.d.n15.name" }
        ]
      },
      {
        "name":"Got any fancy demon blessing?",
        "locname": "adv.debug_map.83.d.n17.name",
        "text": "Give me that Treasure of yours...\n(+1 health, Manasight, move speed 120%, Lord of the Pit starts in play)",
        "loctext": "adv.debug_map.83.d.n16.text",
        "condition": [ {"colorIdentity": "B"}, { "item": "Treasure" }, { "hasBlessing":  "Debug Demon", "not": true } ],
        "options": [
          { "name": "That's shady.", "locname": "adv.debug_map.83.d.n18.name"},
          {
            "name": "What can possibly go wrong?",
            "locname": "adv.debug_map.83.d.n19.name",
            "action": [
              { "removeItem": "Treasure", "giveBlessing": { "name": "Debug Demon" , "lifeModifier": 1, "colorView": true, "moveSpeed": 2, "startBattleWithCard": [ "Lord of the Pit" ] } }
            ]
          }
        ]
      },
      {
        "name": "Hey what's your favorite color?",
        "locname": "adv.debug_map.83.d.n21.name",
        "text": "Pink. It's the color of my favorite blood milkshakes.\nVery dark and evil.",
        "loctext": "adv.debug_map.83.d.n20.text",
        "condition": [ {"getQuestFlag":  { "key":"128", "op":"=", "val":1 } } ],
        "options": [
          { "name":  "Thank you Satan.", "locname": "adv.debug_map.83.d.n22.name", "action":  [ { "setQuestFlag":  { "key":"128", "val":3 } } ] }
        ]
      }
    ]
  }
]

[
  {
    "text":"*glub*\n(According to your Fish to English dictionary, he's greeting you)",
    "loctext": "adv.debug_map.91.d.n0.text",
    "options":[
      { "name":"Glub.", "locname": "adv.debug_map.91.d.n1.name" },
      {
        "name": "I like your fishiness. I would like to be blue and smell funny too.",
        "locname": "adv.debug_map.91.d.n3.name",
        "text": "*glub*\n(Your color identify is now blue)",
        "loctext": "adv.debug_map.91.d.n2.text",
        "condition": [ { "colorIdentity": "U", "not": true } ],
        "options": [ { "name": "It's working. Man, I can go eat some krill right now.", "locname": "adv.debug_map.91.d.n4.name", "action": [ { "setColorIdentity": "U" } ]} ]
      },{
        "name": "I talked to the gate. Somehow I think you will find this relevant.",
        "locname": "adv.debug_map.91.d.n6.name",
        "text": "*glub, glub*\n (Fascinating.)",
        "loctext": "adv.debug_map.91.d.n5.text",
        "condition": [ {"checkMapFlag": "gate" } ],
        "options": [
          { "name": "I know, right?", "locname": "adv.debug_map.91.d.n7.name" }
        ]
      }
    ]
  }
]
